    {
      "id": 2,
      "claim": "Classic Nintendo games (ROM files) are protected by copyright.",
      "evidence": "Nintendo holds copyright registrations for its game code, graphics, music, and other assets; copyright lasts for the life of the author plus 70 years (or 95 years for works made for hire).",
      "weight": 0.25,
      "depends_on": []
